style.css:
@-moz-document url("https://www.google.com/"), url("https://www.google.com/webhp") {
html, body {
    background: url("https://i.pinimg.com/736x/7f/27/d6/7f27d60650ab2bc50677198e32b41589.jpg") center center / cover no-repeat fixed !important;
    color: white !important;
  }

  input[type="text"],
  input[type="search"] {
    background-color: black !important;
    color: white !important;
    border: 1px solid white !important;
    border-radius: 10px !important;
    padding: 8px !important;
  }

  input[type="text"]:focus,
  input[type="search"]:focus {
    outline: none !important;
    box-shadow: 0 0 5px white !important;
  }
}

@-moz-document regexp("^(?!https://www\.google\.com(/|/webhp)?$).*") {
html, body {
    background: url("https://i.pinimg.com/736x/7f/27/d6/7f27d60650ab2bc50677198e32b41589.jpg") center center / cover no-repeat fixed !important;
